package ru.hive13.server;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
import ru.hive13.model.*;
import static ru.hive13.model.Model.*;
import java.util.*;
import java.nio.file.Path;

class DefenseTest {
    @Test void closeRangeShockSpendsItsOwnChargeAndLeavesCreatureAlive(){var e=engine();var c=target(e);assertTrue(cmd(e,"FIRE",Map.of("target",c.id,"weapon","stunner")).accepted());assertEquals(2,DefenseRules.count(e.state.actor(0),"shock_cell"));assertEquals(4,DefenseRules.count(e.state.actor(0),"shell"));assertEquals(5,c.suppressedUntil,.01);assertEquals(1,e.state.creatures.size());}
    @Test void uvAndLoudspeakerProduceRealTimedWorldEffects(){var e=engine();var a=e.state.actor(0);var f=WorldObjects.get("uv");a.roomId=f.room();a.x=f.x();a.y=f.y();var c=new Creature();c.id="C";c.type="ГОНЧАЯ";c.home=c.roomId="A2";c.x=305;c.y=248;e.state.creatures.add(c);assertTrue(cmd(e,"USE_OBJECT",Map.of("target","uv","action","UV")).accepted());e.advance(2.2);assertTrue(c.suppressedUntil>e.state.gameTime);assertEquals(5,e.state.supplies.get("batteries"));assertEquals(1,e.state.creatures.size());f=WorldObjects.get("speaker");a.roomId=f.room();a.x=f.x();a.y=f.y();c.home=c.roomId="B4";c.x=500;c.y=80;c.suppressedUntil=c.immuneUntil=0;assertTrue(cmd(e,"USE_OBJECT",Map.of("target","speaker","action","DECOY")).accepted());e.advance(2.2);assertEquals(4,e.state.supplies.get("batteries"));assertEquals("B3",c.targetRoom);assertTrue(e.state.noises.stream().anyMatch(n->n.source.equals("Громкоговоритель")&&n.expires>e.state.gameTime));}
    @Test void rearmingTransfersSharedSuppliesIntoPersonalCharges(){var e=engine();var a=e.state.actor(0);var f=WorldObjects.get("armory");a.roomId=f.room();a.x=f.x();a.y=f.y();assertTrue(cmd(e,"USE_OBJECT",Map.of("target",f.id(),"action","ARMORY")).accepted());e.advance(8.1);assertTrue(cmd(e,"USE_OBJECT",Map.of("target",f.id(),"action","REARM")).accepted());e.advance(2.1);assertEquals(6,DefenseRules.count(a,"shell"));assertEquals(5,DefenseRules.count(a,"shock_cell"));assertEquals(3,DefenseRules.count(a,"flare"));assertEquals(12,e.state.supplies.get("ammo"));}
    @Test void firingPreservesAnEscapeRouteWhileInterruptingWork(){var e=engine();target(e);var a=e.state.actor(0);assertTrue(cmd(e,"MOVE",Map.of("x",235,"y",170,"mode","RUN")).accepted());var path=new ArrayList<>(a.path);assertTrue(fire(e).accepted());assertEquals(path,a.path);assertEquals("RUN",a.movement);}
    @Test void portableFlashlightDetersWhisperWithoutGridPower(){var e=engine();e.state.actor(1).life=e.state.actor(2).life="DORMANT";var a=e.state.actor(0);a.roomId="A2";a.x=260;a.y=270;a.flashlight=true;e.state.rooms.get("A2").powered=false;var c=new Creature();c.id="W";c.type="ШЕПТУН";c.roomId=c.home="A2";c.x=260;c.y=270;e.state.creatures.add(c);e.advance(4);assertEquals(100,a.hp);a.flashlight=false;e.advance(4);assertTrue(a.hp<100);}
    @Test void failedShotCannotInterruptAnAcceptedRepair(){var e=engine();target(e);e.state.actor(0).task="REPAIR";assertFalse(cmd(e,"FIRE",Map.of("target","missing","weapon","shotgun")).accepted());assertEquals("REPAIR",e.state.actor(0).task);assertTrue(fire(e).accepted());assertEquals("",e.state.actor(0).task);}
    @Test void temporaryBarricadeActuallyClosesThenReleasesTheDoor(){var e=engine();var a=e.state.actor(0);var f=WorldObjects.get("brace");a.x=f.x();a.y=f.y();a.roomId=f.room();assertTrue(cmd(e,"USE_OBJECT",Map.of("target",f.id(),"action","BARRICADE")).accepted());e.advance(5.1);assertFalse(e.state.doors.get("D10").passable());assertEquals(10,e.state.supplies.get("parts"));e.advance(25.1);assertTrue(e.state.doors.get("D10").passable());}
    private GameEngine engine(){var e=new GameEngine(WorldFactory.create("STORY"));e.state.creatures.clear();for(var a:e.state.actors){a.connected=true;a.ready=true;}e.start();return e;}
    private GameEngine.Result cmd(GameEngine e,String type,Object data){return e.command(0,new Packet(type,UUID.randomUUID().toString(),data));}
    private Creature target(GameEngine e){var a=e.state.actor(0);a.roomId="B2";a.x=240;a.y=120;DefenseSystem.complete(e,a,WorldObjects.get("armory"),"ARMORY");var c=new Creature();c.id="TARGET";c.type="ГОНЧАЯ";c.home=c.roomId="B2";c.x=275;c.y=120;e.state.creatures.add(c);return c;}
    private GameEngine.Result fire(GameEngine e){return cmd(e,"FIRE",Map.of("target","TARGET","weapon","shotgun"));}
    @Test void armoryRequiresApproachTimeCostAndOnlyIssuesOnce(){var e=engine();var a=e.state.actor(0);assertTrue(cmd(e,"USE_OBJECT",Map.of("target","armory","action","ARMORY")).accepted());assertEquals(0,DefenseRules.count(a,"shotgun"));e.advance(15);assertEquals(1,DefenseRules.count(a,"shotgun"));assertEquals(4,DefenseRules.count(a,"shell"));assertEquals(14,e.state.supplies.get("ammo"));assertEquals(5,e.state.supplies.get("fuel"));assertFalse(cmd(e,"USE_OBJECT",Map.of("target","armory","action","ARMORY")).accepted());}
    @Test void aShotSpendsOneShellAndNeverRemovesTheCreature(){var e=engine();var c=target(e);assertTrue(fire(e).accepted());assertEquals(3,DefenseRules.count(e.state.actor(0),"shell"));assertEquals(1,e.state.creatures.size());assertTrue(c.suppressedUntil>e.state.gameTime);double x=c.x;e.advance(3);assertEquals(x,c.x);e.advance(4);assertEquals(1,e.state.creatures.size());assertNotEquals("SUPPRESSED",c.state);}
    @Test void suppressionCannotBeStackedOrImmediatelyRepeated(){var e=engine();var c=target(e);assertTrue(fire(e).accepted());assertFalse(fire(e).accepted());e.advance(6.1);assertFalse(fire(e).accepted());assertEquals(3,DefenseRules.count(e.state.actor(0),"shell"));assertTrue(c.immuneUntil>e.state.gameTime);}
    @Test void duplicateShotIsIdempotent(){var e=engine();target(e);var p=new Packet("FIRE","same-shot",Map.of("target","TARGET","weapon","shotgun"));assertTrue(e.command(0,p).accepted());assertTrue(e.command(0,p).accepted());assertEquals(3,DefenseRules.count(e.state.actor(0),"shell"));}
    @Test void wallsAndClosedDoorsBlockTheShotWithoutSpendingAmmo(){var e=engine();var c=target(e);var a=e.state.actor(0);a.x=280;a.y=102;c.roomId="B3";c.x=350;c.y=102;e.state.doors.get("D02").status=DoorStatus.CLOSED;assertFalse(fire(e).accepted());assertEquals(4,DefenseRules.count(a,"shell"));e.state.doors.get("D02").status=DoorStatus.OPEN;assertTrue(fire(e).accepted());}
    @Test void rangeAndUnconfirmedContactsCannotBeUsedAsRemoteAttacks(){var e=engine();var c=target(e);c.x=280;c.y=180;assertFalse(cmd(e,"FIRE",Map.of("target",c.id,"weapon","stunner")).accepted());c.roomId="B5";c.x=700;c.y=110;assertFalse(fire(e).accepted());assertEquals(4,DefenseRules.count(e.state.actor(0),"shell"));}
    @Test void votingAndEchoCannotFire(){var e=engine();target(e);e.state.phase=Phase.VOTING;assertFalse(fire(e).accepted());e.state.phase=Phase.ACTION;e.state.actor(0).life="ECHO";assertFalse(fire(e).accepted());assertEquals(4,DefenseRules.count(e.state.actor(0),"shell"));}
    @Test void combatAndDoorTimersFreezeDuringVoting(){var e=engine();var c=target(e);assertTrue(fire(e).accepted());double now=e.state.gameTime,until=c.suppressedUntil;e.state.phase=Phase.VOTING;e.advance(2);assertEquals(now,e.state.gameTime);assertEquals(until,c.suppressedUntil);}
    @Test void flareIsLessEffectiveAgainstHoundThanWhisper(){var h=engine();var c=target(h);assertTrue(cmd(h,"FIRE",Map.of("target",c.id,"weapon","flaregun")).accepted());assertEquals(3,c.suppressedUntil,.01);var w=engine();var whisper=target(w);whisper.type="ШЕПТУН";assertTrue(cmd(w,"FIRE",Map.of("target",whisper.id,"weapon","flaregun")).accepted());assertEquals(12,whisper.suppressedUntil,.01);}
    @Test void ordinaryDoorCanBeBreachedButSealedDoorCannot(){var e=engine();var c=new Creature();c.id="C";c.type="ГОНЧАЯ";c.roomId=c.home="B3";c.x=337;c.y=102;e.state.creatures.add(c);var d=e.state.doors.get("D02");d.status=DoorStatus.CLOSED;e.state.noises.add(new Noise("B2","Test",180,40));e.advance(13);assertEquals(DoorStatus.BROKEN,d.status);d.status=DoorStatus.SEALED;c.roomId="B3";c.x=337;c.y=102;e.advance(13);assertEquals(DoorStatus.SEALED,d.status);}
    @Test void hidingEndsOnMovementAndDoesNotDefeatCloseSearch(){var e=engine();e.state.actor(1).life="DORMANT";e.state.actor(2).life="DORMANT";var a=e.state.actor(0);a.roomId="A2";a.x=260;a.y=300;a.hidden=true;var c=new Creature();c.id="C";c.type="ГОНЧАЯ";c.roomId=c.home="A2";c.x=260;c.y=265;e.state.creatures.add(c);e.advance(1);assertEquals(100,a.hp);assertTrue(cmd(e,"MOVE",Map.of("x",260,"y",270,"mode","WALK")).accepted());assertFalse(a.hidden);e.advance(3);assertTrue(a.hp<100);}
    @Test void burnCannotPermanentlyRemoveTheThreat(){var e=engine();var c=target(e);c.roomId=c.home="B4";c.x=520;c.y=70;DefenseSystem.suppress(e,c,90);e.state.progress.put("burn_recover:B4",90d);e.state.rooms.get("B4").biomass=0;e.state.gameTime=91;DefenseSystem.update(e,.1);assertEquals(8,e.state.rooms.get("B4").biomass);assertEquals(1,e.state.creatures.size());e.advance(.1);assertNotEquals("SUPPRESSED",c.state);}
    @Test void chargesSuppressionAndHiddenStateSurviveSaving(@TempDir Path dir)throws Exception{var e=engine();target(e);assertTrue(fire(e).accepted());e.state.actor(1).hidden=true;var file=dir.resolve("defense.json");SaveStore.save(file,e.state);var s=SaveStore.load(file);assertEquals(3,DefenseRules.count(s.actor(0),"shell"));assertTrue(s.creatures.getFirst().suppressedUntil>0);assertTrue(s.actor(1).hidden);}
}
